"use client";

import {
  AlertTriangle, ArrowLeft, BellRing, Boxes, CalendarClock, Check, ChevronRight,
  ClipboardPlus, FileHeart, FileText, History, LayoutDashboard, Loader2, Menu, PackagePlus,
  Plus, Printer, Search, Settings2, ShieldCheck, Stethoscope, Syringe, Trash2, UserPlus,
  UsersRound, X,
} from "lucide-react";
import { FormEvent, ReactNode, useCallback, useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Toaster } from "@/components/ui/sonner";

type Section = "dashboard" | "patients" | "prescriptions" | "applications" | "stock" | "reminders" | "admin";
type User = { id: number; nome: string; email: string; papel: "medico_admin" | "recepcao" };
type Patient = { id: number; nome: string; nascimento: string; cpf: string | null; telefone: string; endereco: string; contatoEmergencia: string; observacoesAdmin: string };
type Product = { id: number; nome: string; principioAtivo: string; apresentacao: string; unidade: string; estoqueMinimo: number };
type Lot = { id: number; produtoId: number; numero: string; validade: string; recebidoEm: string; saldo: number };
type Reminder = { id: number; pacienteId: number; pacienteNome: string; telefone: string; produtoId: number | null; produtoNome: string | null; dataPrevista: string; estado: string; notaAdministrativa: string };
type PrescriptionItem = { id: number; produtoId: number; produtoNome: string; apresentacao: string; concentracao: string; dose: string; via: string; quantidade: number; instrucoes: string; recorrenciaDias: number | null };
type Prescription = { id: number; pacienteId: number; pacienteNome: string; medicoNome: string; estado: string; criadoEm: string; finalizadoEm: string | null; observacoes: string; items: PrescriptionItem[] };
type ApplicationItem = { id: number; itemPrescricaoId: number; produtoId: number; produtoNome: string; loteId: number; loteNumero: string; quantidade: number };
type Application = { id: number; prescricaoId: number; pacienteId: number; pacienteNome: string; localAplicacao: string; observacoes: string; reacao: string; aplicadoEm: string; estornadaEm: string | null; items: ApplicationItem[] };
type Symptom = { id: number; nome: string };
type Assessment = { id: number; pacienteId: number; sintomaId: number; sintomaNome: string; intensidade: number; observacao: string; avaliadoEm: string };
type Chart = { id: number; pacienteId: number; anamnese: string; alergias: string; condicoes: string; medicamentos: string; atualizadoEm: string };
type Evolution = { id: number; pacienteId: number; autorNome: string; texto: string; tipo: string; evolucaoOriginalId: number | null; criadoEm: string };
type AuditRow = { id: number; usuarioNome: string | null; acao: string; entidade: string; entidadeId: string; detalhes: string; criadoEm: string };
type UserRow = { id: number; nome: string; email: string; papel: "medico_admin" | "recepcao"; ativo: boolean };
type Payload = { user: User; patients: Patient[]; products: Product[]; lots: Lot[]; reminders: Reminder[]; prescriptions: Prescription[]; applications: Application[]; symptoms: Symptom[]; assessments: Assessment[]; charts: Chart[]; evolutions: Evolution[]; audit: AuditRow[]; users: UserRow[]; settings: { expiryAlertDays: number } };
type DraftItem = { key: string; produtoId: string; dose: string; via: string; quantidade: string; instrucoes: string; recorrenciaDias: string };

const nav = [
  ["dashboard", "Visão geral", LayoutDashboard], ["patients", "Pacientes", UsersRound], ["prescriptions", "Prescrições", FileText],
  ["applications", "Aplicações", Syringe], ["stock", "Estoque", Boxes], ["reminders", "Recorrências", CalendarClock], ["admin", "Administração", Settings2],
] as const;
const empty: Payload = { user: { id: 0, nome: "", email: "", papel: "medico_admin" }, patients: [], products: [], lots: [], reminders: [], prescriptions: [], applications: [], symptoms: [], assessments: [], charts: [], evolutions: [], audit: [], users: [], settings: { expiryAlertDays: 60 } };
const today = () => new Date().toLocaleDateString("en-CA", { timeZone: "America/Fortaleza" });
const fmtDate = (value?: string | null) => value ? new Intl.DateTimeFormat("pt-BR", { day: "2-digit", month: "short", year: "numeric", timeZone: "America/Fortaleza" }).format(new Date(value.includes("T") ? value : `${value}T12:00:00-03:00`)) : "—";
const fmtDateTime = (value: string) => new Intl.DateTimeFormat("pt-BR", { dateStyle: "short", timeStyle: "short", timeZone: "America/Fortaleza" }).format(new Date(value));
const initials = (name: string) => name.split(" ").filter(Boolean).slice(0, 2).map((word) => word[0]).join("").toUpperCase();
const names = (items: { produtoNome: string }[]) => items.map((item) => item.produtoNome).join(" + ");
async function post(body: Record<string, unknown>) { const response = await fetch("/api/cti", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(body) }); const result = await response.json() as { error?: string }; if (!response.ok) throw new Error(result.error || "Não foi possível concluir a operação."); }

function Panel({ children, className = "" }: { children: ReactNode; className?: string }) { return <section className={`rounded-2xl border border-slate-200/75 bg-white shadow-[0_10px_35px_rgba(17,42,86,.055)] ${className}`}>{children}</section>; }
function Field({ label, children, hint }: { label: string; children: ReactNode; hint?: string }) { return <label className="block space-y-1.5"><span className="text-sm font-semibold text-slate-700">{label}</span>{children}{hint && <span className="block text-xs leading-5 text-slate-500">{hint}</span>}</label>; }
function PageHeading({ eyebrow, title, text, action }: { eyebrow: string; title: string; text: string; action?: ReactNode }) { return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-cyan-700">{eyebrow}</p><h1 className="mt-2 text-2xl font-semibold tracking-tight text-slate-950 sm:text-3xl">{title}</h1><p className="mt-1.5 text-[0.95rem] text-slate-500">{text}</p></div>{action && <div className="flex shrink-0 gap-2">{action}</div>}</div>; }
function Status({ status }: { status: string }) { const map: Record<string, string> = { finalizada: "bg-blue-50 text-blue-700 ring-blue-100", parcialmente_aplicada: "bg-amber-50 text-amber-800 ring-amber-100", aplicada: "bg-emerald-50 text-emerald-700 ring-emerald-100", proximo: "bg-cyan-50 text-cyan-800 ring-cyan-100", vencido: "bg-rose-50 text-rose-700 ring-rose-100", contatado: "bg-violet-50 text-violet-700 ring-violet-100", concluido: "bg-emerald-50 text-emerald-700 ring-emerald-100" }; return <span className={`inline-flex rounded-full px-2.5 py-1 text-xs font-bold capitalize ring-1 ${map[status] ?? "bg-slate-100 text-slate-600 ring-slate-200"}`}>{status.replaceAll("_", " ")}</span>; }
function Empty({ icon: Icon, title, text, action }: { icon: typeof Search; title: string; text: string; action?: ReactNode }) { return <div className="grid min-h-60 place-items-center px-6 py-10 text-center"><div><span className="mx-auto grid h-12 w-12 place-items-center rounded-2xl bg-cyan-50 text-cyan-700"><Icon className="h-5 w-5" /></span><h2 className="mt-4 font-semibold text-slate-900">{title}</h2><p className="mx-auto mt-1 max-w-sm text-sm leading-6 text-slate-500">{text}</p>{action && <div className="mt-5">{action}</div>}</div></div>; }

export function CtiApp({ signedInName }: { signedInName: string }) {
  const [data, setData] = useState<Payload>(empty), [loading, setLoading] = useState(true), [error, setError] = useState("");
  const [section, setSection] = useState<Section>("dashboard"), [menu, setMenu] = useState(false), [search, setSearch] = useState("");
  const [patientId, setPatientId] = useState<number | null>(null), [patientDialog, setPatientDialog] = useState(false), [stockDialog, setStockDialog] = useState(false), [rxDialog, setRxDialog] = useState(false);
  const [applyRx, setApplyRx] = useState<Prescription | null>(null), [printRx, setPrintRx] = useState<Prescription | null>(null), [saving, setSaving] = useState(false);
  const load = useCallback(async () => { try { setError(""); const response = await fetch("/api/cti", { cache: "no-store" }); const payload = await response.json() as Payload & { error?: string }; if (!response.ok) throw new Error(payload.error); setData(payload); } catch (reason) { setError(reason instanceof Error ? reason.message : "Não foi possível carregar o sistema."); } finally { setLoading(false); } }, []);
  useEffect(() => { void load(); }, [load]);
  const run = async (action: Record<string, unknown>, success: string, close?: () => void) => { setSaving(true); try { await post(action); toast.success(success); close?.(); await load(); } catch (reason) { toast.error(reason instanceof Error ? reason.message : "Falha ao salvar."); } finally { setSaving(false); } };
  const doctor = data.user.papel === "medico_admin", userName = data.user.nome || signedInName;
  const selectedPatient = data.patients.find((patient) => patient.id === patientId) ?? null;
  const filteredPatients = data.patients.filter((patient) => `${patient.nome} ${patient.cpf ?? ""} ${patient.telefone}`.toLowerCase().includes(search.toLowerCase()));
  const balances = data.products.map((product) => ({ ...product, balance: data.lots.filter((lot) => lot.produtoId === product.id).reduce((sum, lot) => sum + lot.saldo, 0) }));
  const lowStock = balances.filter((product) => product.balance <= product.estoqueMinimo);
  const expiring = data.lots.filter((lot) => lot.saldo > 0 && lot.validade <= new Date(Date.now() + data.settings.expiryAlertDays * 86400000).toISOString().slice(0, 10));
  const pending = data.prescriptions.filter((rx) => ["finalizada", "parcialmente_aplicada"].includes(rx.estado));
  const openReminders = data.reminders.filter((reminder) => !["concluido", "cancelado"].includes(reminder.estado));
  const changeSection = (next: Section) => { setSection(next); setMenu(false); setPatientId(null); };
  if (loading) return <div className="grid min-h-screen place-items-center bg-[#f6f9fc]"><div className="text-center"><Loader2 className="mx-auto h-8 w-8 animate-spin text-cyan-700" /><p className="mt-3 text-sm text-slate-500">Abrindo ambiente protegido…</p></div></div>;
  if (error) return <div className="grid min-h-screen place-items-center bg-[#f6f9fc] p-6"><Panel className="max-w-md p-7 text-center"><AlertTriangle className="mx-auto h-8 w-8 text-rose-500" /><h1 className="mt-4 text-xl font-semibold">Não foi possível abrir o sistema</h1><p className="mt-2 text-sm leading-6 text-slate-500">{error}</p><Button className="mt-5" onClick={() => { setLoading(true); void load(); }}>Tentar novamente</Button></Panel></div>;
  return <main className="min-h-screen bg-[#f6f9fc] text-slate-900">
    <aside className={`fixed inset-y-0 left-0 z-40 flex w-[276px] flex-col bg-[#071c42] px-4 py-5 text-white shadow-2xl transition-transform duration-300 lg:translate-x-0 print:hidden ${menu ? "translate-x-0" : "-translate-x-full"}`}>
      <div className="flex items-center gap-3 px-3 pb-6"><img src="/logo.jpg" alt="CTI" className="h-12 w-12 rounded-2xl bg-white object-contain p-1.5" /><div><strong className="block text-lg tracking-[.18em]">CTI</strong><span className="text-xs text-cyan-200">Gestão clínica</span></div><button className="ml-auto rounded-lg p-2 text-blue-200 lg:hidden" onClick={() => setMenu(false)} aria-label="Fechar menu"><X className="h-5 w-5" /></button></div>
      <nav className="space-y-1" aria-label="Navegação principal">{nav.filter(([id]) => id !== "admin" || doctor).map(([id, label, Icon]) => <button key={id} onClick={() => changeSection(id)} className={`flex w-full items-center gap-3 rounded-xl px-3.5 py-3 text-left text-sm font-semibold transition ${section === id ? "bg-white text-[#071c42] shadow-[0_8px_20px_rgba(0,0,0,.18)]" : "text-blue-100 hover:bg-white/10 hover:text-white"}`}><Icon className="h-[18px] w-[18px]" />{label}</button>)}</nav>
      <div className="mt-auto rounded-2xl border border-cyan-300/15 bg-white/5 p-4"><div className="flex items-center gap-2 text-sm font-semibold"><ShieldCheck className="h-4 w-4 text-cyan-300" />Ambiente protegido</div><p className="mt-1.5 text-xs leading-5 text-blue-100">Acesso clínico restrito e registros rastreáveis.</p></div>
    </aside>
    {menu && <button aria-label="Fechar menu" className="fixed inset-0 z-30 bg-slate-950/45 lg:hidden" onClick={() => setMenu(false)} />}
    <section className="min-h-screen lg:pl-[276px] print:pl-0"><header className="sticky top-0 z-20 flex h-[76px] items-center gap-3 border-b border-slate-200/80 bg-white/90 px-4 backdrop-blur-xl sm:px-7 lg:px-9 print:hidden"><button className="rounded-xl border border-slate-200 bg-white p-2.5 lg:hidden" aria-label="Abrir menu" onClick={() => setMenu(true)}><Menu className="h-5 w-5" /></button><div className="relative hidden max-w-md flex-1 sm:block"><Search className="absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" /><Input aria-label="Buscar paciente" value={search} onFocus={() => setSection("patients")} onChange={(event) => setSearch(event.target.value)} className="h-11 rounded-xl border-slate-200 bg-slate-50 pl-10" placeholder="Buscar paciente por nome, CPF ou telefone" /></div><div className="ml-auto flex items-center gap-3"><button aria-label="Abrir recorrências" onClick={() => setSection("reminders")} className="relative rounded-xl border border-slate-200 bg-white p-2.5 text-slate-600"><BellRing className="h-5 w-5" />{openReminders.length > 0 && <span className="absolute -right-1 -top-1 grid h-4 min-w-4 place-items-center rounded-full bg-rose-500 px-1 text-[10px] font-bold text-white">{openReminders.length}</span>}</button><div className="hidden text-right sm:block"><strong className="block text-sm">{userName}</strong><span className="text-xs text-slate-500">{doctor ? "Médico administrador" : "Recepção"}</span></div><span className="grid h-10 w-10 place-items-center rounded-xl bg-gradient-to-br from-[#07265b] to-cyan-700 text-sm font-bold text-white">{initials(userName)}</span></div></header>
      <div className="mx-auto max-w-[1500px] p-4 sm:p-7 lg:p-9 print:hidden">
        {section === "dashboard" && <Dashboard data={data} lowStock={lowStock.length} expiring={expiring.length} pending={pending.length} onSection={changeSection} onNewPatient={() => setPatientDialog(true)} onNewRx={() => setRxDialog(true)} doctor={doctor} userName={userName} />}
        {section === "patients" && !selectedPatient && <Patients rows={filteredPatients} search={search} setSearch={setSearch} onNew={() => setPatientDialog(true)} onOpen={setPatientId} />}
        {section === "patients" && selectedPatient && <PatientDetail patient={selectedPatient} data={data} doctor={doctor} run={run} saving={saving} onBack={() => setPatientId(null)} onNewRx={() => setRxDialog(true)} />}
        {section === "prescriptions" && <Prescriptions rows={data.prescriptions} doctor={doctor} onNew={() => setRxDialog(true)} onPrint={(rx) => { setPrintRx(rx); window.setTimeout(() => window.print(), 120); }} />}
        {section === "applications" && <Applications pending={pending} applied={data.applications} lots={data.lots} doctor={doctor} onApply={setApplyRx} />}
        {section === "stock" && <Stock products={balances} lots={data.lots} onReceive={() => setStockDialog(true)} />}
        {section === "reminders" && <Reminders rows={data.reminders} run={run} saving={saving} />}
        {section === "admin" && <Admin data={data} doctor={doctor} run={run} saving={saving} />}
      </div></section>
    <PatientDialog open={patientDialog} setOpen={setPatientDialog} run={run} saving={saving} /><StockDialog open={stockDialog} setOpen={setStockDialog} products={data.products} run={run} saving={saving} /><PrescriptionDialog open={rxDialog} setOpen={setRxDialog} patients={data.patients} products={data.products} run={run} saving={saving} /><ApplicationDialog rx={applyRx} setRx={setApplyRx} lots={data.lots} applications={data.applications} run={run} saving={saving} />{printRx && <PrescriptionPrint rx={printRx} onClose={() => setPrintRx(null)} />}<Toaster position="top-right" richColors />
  </main>;
}

function Dashboard({ data, lowStock, expiring, pending, onSection, onNewPatient, onNewRx, doctor, userName }: { data: Payload; lowStock: number; expiring: number; pending: number; onSection: (section: Section) => void; onNewPatient: () => void; onNewRx: () => void; doctor: boolean; userName: string }) { const overdue = data.reminders.filter((item) => item.dataPrevista < today() && !["concluido", "cancelado"].includes(item.estado)); const cards = [["Retornos vencidos", overdue.length, "Contato prioritário", BellRing, "reminders"], ["Aplicações pendentes", pending, "Aguardando confirmação", Syringe, "applications"], ["Estoque baixo", lowStock, "No mínimo ou abaixo", Boxes, "stock"], ["Lotes a vencer", expiring, "Nos próximos 60 dias", AlertTriangle, "stock"]] as const; return <><PageHeading eyebrow="Operação diária" title={`Olá, ${userName.split(" ")[0]}`} text="Uma visão objetiva do que precisa de atenção hoje." action={<><Button variant="outline" onClick={onNewPatient}><UserPlus />Novo paciente</Button>{doctor && <Button onClick={onNewRx}><ClipboardPlus />Nova prescrição</Button>}</>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{cards.map(([label, value, detail, Icon, section]) => <button key={label} onClick={() => onSection(section)} className="rounded-2xl border border-slate-200/80 bg-white p-5 text-left shadow-[0_10px_35px_rgba(17,42,86,.055)] transition hover:-translate-y-0.5 hover:border-cyan-200 hover:shadow-lg"><span className="grid h-10 w-10 place-items-center rounded-xl bg-cyan-50 text-cyan-700"><Icon className="h-5 w-5" /></span><strong className="mt-5 block text-2xl tracking-tight">{value}</strong><span className="mt-1 block text-sm font-semibold text-slate-700">{label}</span><span className="mt-1 block text-xs text-slate-500">{detail}</span></button>)}</div><div className="mt-6 grid gap-6 xl:grid-cols-[1.3fr_.7fr]"><Panel><div className="flex items-center justify-between border-b border-slate-100 px-6 py-5"><div><h2 className="font-semibold">Próximos retornos</h2><p className="mt-1 text-sm text-slate-500">Acompanhe contatos sem expor dados clínicos.</p></div><button className="text-sm font-semibold text-cyan-700" onClick={() => onSection("reminders")}>Ver todos</button></div>{data.reminders.length ? <div className="divide-y divide-slate-100">{data.reminders.slice(0, 5).map((item) => <div key={item.id} className="flex items-center gap-3 px-6 py-4"><span className="grid h-9 w-9 place-items-center rounded-xl bg-slate-100 text-xs font-bold text-slate-700">{initials(item.pacienteNome)}</span><div className="min-w-0 flex-1"><strong className="block truncate text-sm">{item.pacienteNome}</strong><span className="text-xs text-slate-500">{item.telefone}</span></div><span className="hidden text-sm text-slate-600 sm:block">{fmtDate(item.dataPrevista)}</span><Status status={item.dataPrevista < today() && item.estado === "proximo" ? "vencido" : item.estado} /></div>)}</div> : <Empty icon={CalendarClock} title="Nenhum retorno programado" text="Os retornos serão criados após aplicações recorrentes." />}</Panel><Panel className="bg-[linear-gradient(135deg,#071c42_0%,#0d4f78_100%)] p-6 text-white"><span className="grid h-11 w-11 place-items-center rounded-xl bg-white/10 text-cyan-200"><Stethoscope className="h-5 w-5" /></span><h2 className="mt-8 text-xl font-semibold">Atendimento com rastreabilidade</h2><p className="mt-2 text-sm leading-6 text-blue-100">Prescrição, aplicação e lote permanecem conectados em cada atendimento.</p>{doctor && <Button className="mt-7 bg-white text-[#071c42] hover:bg-cyan-50" onClick={onNewRx}>Criar prescrição</Button>}</Panel></div></>; }
function Patients({ rows, search, setSearch, onNew, onOpen }: { rows: Patient[]; search: string; setSearch: (value: string) => void; onNew: () => void; onOpen: (id: number) => void }) { return <><PageHeading eyebrow="Cadastro e acompanhamento" title="Pacientes" text="Localize e acompanhe cada histórico com segurança." action={<Button onClick={onNew}><UserPlus />Novo paciente</Button>} /><Panel><div className="border-b border-slate-100 p-5"><div className="relative max-w-xl"><Search className="absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" /><Input value={search} onChange={(event) => setSearch(event.target.value)} className="pl-10" placeholder="Buscar por nome, CPF ou telefone" /></div></div>{rows.length ? <div className="divide-y divide-slate-100">{rows.map((patient) => <button key={patient.id} onClick={() => onOpen(patient.id)} className="flex w-full items-center gap-4 px-5 py-4 text-left transition hover:bg-cyan-50/45"><span className="grid h-11 w-11 shrink-0 place-items-center rounded-xl bg-[#eaf4fa] text-sm font-bold text-[#0b4c73]">{initials(patient.nome)}</span><div className="min-w-0 flex-1"><strong className="block truncate">{patient.nome}</strong><span className="text-sm text-slate-500">Nascimento: {fmtDate(patient.nascimento)}</span></div><div className="hidden text-right sm:block"><span className="block text-sm font-medium">{patient.telefone}</span><span className="text-xs text-slate-400">{patient.cpf ? `CPF ${patient.cpf}` : "CPF não informado"}</span></div><ChevronRight className="h-5 w-5 text-slate-400" /></button>)}</div> : <Empty icon={UsersRound} title="Nenhum paciente encontrado" text={search ? "Tente outro nome, CPF ou telefone." : "Cadastre o primeiro paciente para iniciar o acompanhamento."} action={!search ? <Button onClick={onNew}>Cadastrar paciente</Button> : undefined} />}</Panel></>; }
function PatientDetail({ patient, data, doctor, run, saving, onBack, onNewRx }: { patient: Patient; data: Payload; doctor: boolean; run: (action: Record<string, unknown>, success: string, close?: () => void) => Promise<void>; saving: boolean; onBack: () => void; onNewRx: () => void }) {
  const chart = data.charts.find((item) => item.pacienteId === patient.id), evolutions = data.evolutions.filter((item) => item.pacienteId === patient.id), assessments = data.assessments.filter((item) => item.pacienteId === patient.id); const [scores, setScores] = useState<Record<number, number>>({});
  const saveChart = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const form = new FormData(event.currentTarget); void run({ action: "save_chart", pacienteId: patient.id, anamnese: form.get("anamnese"), alergias: form.get("alergias"), condicoes: form.get("condicoes"), medicamentos: form.get("medicamentos") }, "Prontuário atualizado."); };
  return <><button onClick={onBack} className="mb-5 inline-flex items-center gap-2 text-sm font-semibold text-slate-600 hover:text-cyan-700"><ArrowLeft className="h-4 w-4" />Voltar para pacientes</button><div className="rounded-2xl bg-[#071c42] px-6 py-7 text-white sm:px-8"><div className="flex flex-col gap-4 sm:flex-row sm:items-center"><span className="grid h-14 w-14 place-items-center rounded-2xl bg-white/10 text-lg font-bold text-cyan-100">{initials(patient.nome)}</span><div className="min-w-0 flex-1"><h1 className="truncate text-2xl font-semibold">{patient.nome}</h1><p className="mt-1 text-sm text-blue-100">{patient.telefone} · Nascimento {fmtDate(patient.nascimento)}</p></div>{doctor && <Button className="bg-white text-[#071c42] hover:bg-cyan-50" onClick={onNewRx}><ClipboardPlus />Nova prescrição</Button>}</div></div><div className="mt-6 grid gap-6 xl:grid-cols-[1.2fr_.8fr]">{doctor ? <Panel className="p-6"><h2 className="font-semibold">Prontuário clínico</h2><p className="mt-1 text-sm text-slate-500">Registre informações relevantes para o atendimento.</p><form className="mt-6 grid gap-4 sm:grid-cols-2" onSubmit={saveChart}><Field label="Anamnese"><Textarea name="anamnese" rows={4} defaultValue={chart?.anamnese} /></Field><Field label="Alergias"><Textarea name="alergias" rows={4} defaultValue={chart?.alergias} /></Field><Field label="Condições clínicas"><Textarea name="condicoes" rows={4} defaultValue={chart?.condicoes} /></Field><Field label="Medicamentos em uso"><Textarea name="medicamentos" rows={4} defaultValue={chart?.medicamentos} /></Field><div className="sm:col-span-2 flex justify-end"><Button disabled={saving}>Salvar prontuário</Button></div></form></Panel> : <Panel className="p-6"><h2 className="font-semibold">Dados administrativos</h2><dl className="mt-5 grid gap-4 text-sm"><div><dt className="text-slate-500">Endereço</dt><dd className="mt-1 font-medium">{patient.endereco || "Não informado"}</dd></div><div><dt className="text-slate-500">Contato de emergência</dt><dd className="mt-1 font-medium">{patient.contatoEmergencia || "Não informado"}</dd></div></dl></Panel>}<Panel className="p-6"><h2 className="font-semibold">Linha do tempo de vitaminas</h2><div className="mt-5 space-y-4">{data.applications.filter((application) => application.pacienteId === patient.id).slice(0, 6).map((application) => <div key={application.id} className="border-l-2 border-cyan-300 pl-4"><span className="text-xs font-semibold text-cyan-700">APLICADA · {fmtDate(application.aplicadoEm)}</span><strong className="mt-1 block text-sm">{names(application.items)}</strong><span className="text-xs text-slate-500">{application.items.map((item) => `Lote ${item.loteNumero}`).join(" · ")}</span></div>)}{!data.applications.some((application) => application.pacienteId === patient.id) && <p className="text-sm text-slate-500">Nenhuma aplicação registrada.</p>}</div></Panel></div>{doctor && <div className="mt-6 grid gap-6 xl:grid-cols-2"><Panel className="p-6"><h2 className="font-semibold">Evolução clínica</h2><form className="mt-4" onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); void run({ action: "add_evolution", pacienteId: patient.id, texto: form.get("texto") }, "Evolução registrada.", () => (event.currentTarget as HTMLFormElement).reset()); }}><Textarea name="texto" required rows={4} placeholder="Descreva a evolução do atendimento" /><div className="mt-3 flex justify-end"><Button disabled={saving}><Plus />Adicionar evolução</Button></div></form><div className="mt-6 space-y-4">{evolutions.slice(0, 5).map((evolution) => <article key={evolution.id} className="rounded-xl bg-slate-50 p-4"><div className="flex justify-between gap-3"><strong className="text-sm">{evolution.tipo === "adendo" ? "Adendo" : "Evolução"}</strong><time className="text-xs text-slate-400">{fmtDateTime(evolution.criadoEm)}</time></div><p className="mt-2 text-sm leading-6 text-slate-600">{evolution.texto}</p></article>)}</div></Panel><Panel className="p-6"><h2 className="font-semibold">Marcadores de sintomas</h2><p className="mt-1 text-sm text-slate-500">Intensidade de 0 a 10 no atendimento atual.</p><form className="mt-5 space-y-4" onSubmit={(event) => { event.preventDefault(); const values = data.symptoms.filter((symptom) => scores[symptom.id] !== undefined).map((symptom) => ({ sintomaId: symptom.id, intensidade: scores[symptom.id] })); void run({ action: "add_symptom_assessment", pacienteId: patient.id, values }, "Sintomas registrados.", () => setScores({})); }}>{data.symptoms.map((symptom) => <div key={symptom.id} className="rounded-xl bg-slate-50 p-3"><div className="flex justify-between text-sm"><span className="font-medium">{symptom.nome}</span><strong className="text-cyan-700">{scores[symptom.id] ?? "—"}</strong></div><input className="mt-3 w-full accent-cyan-700" type="range" min="0" max="10" value={scores[symptom.id] ?? 0} onChange={(event) => setScores((current) => ({ ...current, [symptom.id]: Number(event.target.value) }))} /></div>)}<div className="flex justify-end"><Button disabled={saving || !Object.keys(scores).length}>Salvar avaliação</Button></div></form>{assessments.length > 0 && <p className="mt-4 text-xs text-slate-500">Última avaliação: {fmtDateTime(assessments[0].avaliadoEm)}</p>}</Panel></div>}</>;
}

function Prescriptions({ rows, doctor, onNew, onPrint }: { rows: Prescription[]; doctor: boolean; onNew: () => void; onPrint: (rx: Prescription) => void }) { if (!doctor) return <Restricted />; return <><PageHeading eyebrow="Conduta médica" title="Prescrições" text="Documentos finalizados permanecem bloqueados e preservam o histórico." action={<Button onClick={onNew}><Plus />Nova prescrição</Button>} /><Panel>{rows.length ? <div className="divide-y divide-slate-100">{rows.map((rx) => <div key={rx.id} className="flex flex-wrap items-center gap-4 p-5"><span className="grid h-11 w-11 place-items-center rounded-xl bg-cyan-50 text-cyan-700"><FileHeart className="h-5 w-5" /></span><div className="min-w-[180px] flex-1"><strong className="block">{rx.pacienteNome}</strong><span className="text-sm text-slate-500">#{String(rx.id).padStart(5, "0")} · {fmtDate(rx.criadoEm)}</span></div><div className="min-w-[200px]"><span className="text-xs font-bold uppercase tracking-wide text-slate-400">Itens prescritos</span><strong className="mt-1 block text-sm">{names(rx.items)}</strong><span className="mt-1 block text-xs text-slate-500">{rx.items.map((item) => `${item.dose} · ${item.via}`).join("  |  ")}</span></div><Status status={rx.estado} /><Button variant="outline" size="sm" onClick={() => onPrint(rx)}><Printer />PDF</Button></div>)}</div> : <Empty icon={FileText} title="Nenhuma prescrição" text="Crie uma prescrição para um paciente cadastrado." action={<Button onClick={onNew}>Criar prescrição</Button>} />}</Panel></>; }
function pendingItems(rx: Prescription, applications: Application[]) { const applied = new Set(applications.filter((application) => application.prescricaoId === rx.id && !application.estornadaEm).flatMap((application) => application.items.map((item) => item.itemPrescricaoId))); return rx.items.filter((item) => !applied.has(item.id)); }
function Applications({ pending, applied, lots, doctor, onApply }: { pending: Prescription[]; applied: Application[]; lots: Lot[]; doctor: boolean; onApply: (rx: Prescription) => void }) { if (!doctor) return <Restricted />; return <><PageHeading eyebrow="Confirmação e rastreabilidade" title="Aplicações" text="Cada item recebe um lote e baixa o estoque somente após confirmação." /><div className="grid gap-6 xl:grid-cols-2"><Panel><div className="border-b border-slate-100 px-6 py-5"><h2 className="font-semibold">Aguardando aplicação</h2></div>{pending.length ? <div className="divide-y divide-slate-100">{pending.map((rx) => { const items = pendingItems(rx, applied), available = items.some((item) => lots.some((lot) => lot.produtoId === item.produtoId && lot.saldo >= item.quantidade && lot.validade >= today())); return <div key={rx.id} className="p-5"><div className="flex items-start gap-3"><span className="grid h-10 w-10 place-items-center rounded-xl bg-amber-50 text-amber-700"><Syringe className="h-5 w-5" /></span><div className="min-w-0 flex-1"><strong className="block">{rx.pacienteNome}</strong><span className="mt-1 block text-sm text-slate-500">{names(items)}</span><span className="mt-1 block text-xs text-slate-400">{items.length} item(ns) pendente(s)</span></div><Status status={rx.estado} /></div><div className="mt-4 flex items-center justify-between rounded-xl bg-slate-50 px-3 py-3"><span className="text-xs text-slate-500">{available ? "Lotes válidos disponíveis" : "Sem lote válido com saldo"}</span><Button size="sm" disabled={!available} onClick={() => onApply(rx)}>Confirmar</Button></div></div>; })}</div> : <Empty icon={Check} title="Tudo em dia" text="Não há prescrições aguardando aplicação." />}</Panel><Panel><div className="border-b border-slate-100 px-6 py-5"><h2 className="font-semibold">Aplicações recentes</h2></div>{applied.length ? <div className="divide-y divide-slate-100">{applied.slice(0, 10).map((application) => <div key={application.id} className="flex items-center gap-3 p-5"><span className="grid h-10 w-10 place-items-center rounded-xl bg-emerald-50 text-emerald-700"><Check className="h-5 w-5" /></span><div className="min-w-0 flex-1"><strong className="block truncate">{application.pacienteNome}</strong><span className="mt-1 block truncate text-sm text-slate-500">{application.items.map((item) => `${item.produtoNome} · Lote ${item.loteNumero}`).join("  |  ")}</span></div><time className="text-xs text-slate-400">{fmtDateTime(application.aplicadoEm)}</time></div>)}</div> : <Empty icon={History} title="Sem aplicações" text="As aplicações confirmadas aparecerão com lote e horário." />}</Panel></div></>; }
function Stock({ products, lots, onReceive }: { products: (Product & { balance: number })[]; lots: Lot[]; onReceive: () => void }) { return <><PageHeading eyebrow="Lotes, validade e saldo" title="Estoque de injetáveis" text="O lote válido com vencimento mais próximo tem prioridade." action={<Button onClick={onReceive}><PackagePlus />Registrar entrada</Button>} /><div className="grid gap-4 md:grid-cols-2">{products.map((product) => <Panel key={product.id} className="p-5"><div className="flex items-start justify-between gap-4"><div><span className="text-xs font-bold uppercase tracking-[.14em] text-cyan-700">{product.principioAtivo}</span><h2 className="mt-2 text-lg font-semibold">{product.nome}</h2><p className="text-sm text-slate-500">{product.apresentacao}</p></div><span className={`grid min-w-16 place-items-center rounded-xl px-3 py-2 text-xl font-semibold ${product.balance <= product.estoqueMinimo ? "bg-rose-50 text-rose-700" : "bg-emerald-50 text-emerald-700"}`}>{product.balance}</span></div><div className="mt-5 border-t border-slate-100 pt-4"><div className="mb-2 flex justify-between text-xs text-slate-400"><span>Lotes ativos</span><span>Mínimo: {product.estoqueMinimo}</span></div><div className="space-y-2">{lots.filter((lot) => lot.produtoId === product.id && lot.saldo > 0).map((lot) => <div key={lot.id} className="flex items-center justify-between rounded-xl bg-slate-50 px-3 py-2.5 text-sm"><span>Lote <strong>{lot.numero}</strong></span><span className={lot.validade < today() ? "font-semibold text-rose-600" : "text-slate-500"}>{lot.saldo} · {fmtDate(lot.validade)}</span></div>)}{!lots.some((lot) => lot.produtoId === product.id && lot.saldo > 0) && <p className="py-2 text-sm text-slate-400">Nenhum lote com saldo.</p>}</div></div></Panel>)}</div></>; }
function Reminders({ rows, run, saving }: { rows: Reminder[]; run: (action: Record<string, unknown>, success: string, close?: () => void) => Promise<void>; saving: boolean }) { return <><PageHeading eyebrow="Acompanhamento ativo" title="Recorrências" text="Organize contatos sem expor informações clínicas à recepção." /><Panel>{rows.length ? <div className="divide-y divide-slate-100">{rows.map((item) => <div key={item.id} className="flex flex-wrap items-center gap-4 p-5"><span className="grid h-11 w-11 place-items-center rounded-xl bg-cyan-50 text-sm font-bold text-cyan-800">{initials(item.pacienteNome)}</span><div className="min-w-[180px] flex-1"><strong className="block">{item.pacienteNome}</strong><span className="text-sm text-slate-500">{item.telefone}</span></div><div className="min-w-[150px]"><span className="text-xs text-slate-400">RETORNO</span><strong className="mt-1 block text-sm">{item.produtoNome ?? "Acompanhamento"}</strong></div><div className="min-w-[112px]"><span className="text-xs text-slate-400">PREVISTO</span><strong className="mt-1 block text-sm">{fmtDate(item.dataPrevista)}</strong></div><Status status={item.dataPrevista < today() && item.estado === "proximo" ? "vencido" : item.estado} /><div className="flex gap-2"><Button variant="outline" size="sm" disabled={saving || item.estado === "contatado"} onClick={() => void run({ action: "update_reminder", id: item.id, estado: "contatado", notaAdministrativa: "Contato registrado pela equipe." }, "Contato registrado.")}>Contatado</Button><Button size="sm" disabled={saving || item.estado === "concluido"} onClick={() => void run({ action: "update_reminder", id: item.id, estado: "concluido", notaAdministrativa: item.notaAdministrativa }, "Recorrência concluída.")}>Concluir</Button></div></div>)}</div> : <Empty icon={CalendarClock} title="Sem recorrências" text="Aplicações recorrentes criarão o próximo contato automaticamente." />}</Panel></>; }
function Admin({ data, doctor, run, saving }: { data: Payload; doctor: boolean; run: (action: Record<string, unknown>, success: string, close?: () => void) => Promise<void>; saving: boolean }) { if (!doctor) return <Restricted />; return <><PageHeading eyebrow="Configurações clínicas" title="Administração" text="Gerencie equipe, catálogo e parâmetros operacionais." /><div className="grid gap-6 xl:grid-cols-2"><Panel className="p-6"><h2 className="font-semibold">Catálogo de sintomas</h2><form className="mt-4 flex gap-2" onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); void run({ action: "add_symptom", nome: form.get("nome") }, "Sintoma adicionado.", () => (event.currentTarget as HTMLFormElement).reset()); }}><Input name="nome" required placeholder="Novo sintoma" /><Button disabled={saving}>Adicionar</Button></form><div className="mt-5 flex flex-wrap gap-2">{data.symptoms.map((item) => <span key={item.id} className="rounded-full bg-slate-100 px-3 py-1.5 text-sm text-slate-700">{item.nome}</span>)}</div></Panel><Panel className="p-6"><h2 className="font-semibold">Estoque mínimo</h2><div className="mt-4 space-y-3">{data.products.map((product) => <form key={product.id} className="flex items-center gap-3" onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); void run({ action: "update_product_minimum", id: product.id, estoqueMinimo: Number(form.get("minimum")) }, "Estoque mínimo atualizado."); }}><div className="min-w-0 flex-1"><strong className="block text-sm">{product.nome}</strong><span className="text-xs text-slate-500">{product.apresentacao}</span></div><Input className="w-20" name="minimum" type="number" min="0" defaultValue={product.estoqueMinimo} /><Button variant="outline" size="sm" disabled={saving}>Salvar</Button></form>)}</div></Panel><Panel className="p-6 xl:col-span-2"><h2 className="font-semibold">Equipe e permissões</h2><div className="mt-4 divide-y divide-slate-100">{data.users.map((user) => <div key={user.id} className="flex flex-wrap items-center gap-3 py-3"><span className="grid h-9 w-9 place-items-center rounded-xl bg-cyan-50 text-xs font-bold text-cyan-800">{initials(user.nome)}</span><div className="min-w-[220px] flex-1"><strong className="block text-sm">{user.nome}</strong><span className="text-xs text-slate-500">{user.email}</span></div><Select defaultValue={user.papel} onValueChange={(papel) => void run({ action: "update_user_role", id: user.id, papel }, "Perfil atualizado.")}><SelectTrigger className="w-44"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="medico_admin">Médico administrador</SelectItem><SelectItem value="recepcao">Recepção</SelectItem></SelectContent></Select></div>)}</div></Panel></div></>; }
function Restricted() { return <Panel><Empty icon={ShieldCheck} title="Área clínica restrita" text="Seu perfil não possui acesso a este conteúdo." /></Panel>; }
function PatientDialog({ open, setOpen, run, saving }: { open: boolean; setOpen: (value: boolean) => void; run: (action: Record<string, unknown>, success: string, close?: () => void) => Promise<void>; saving: boolean }) { return <Dialog open={open} onOpenChange={setOpen}><DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-2xl"><DialogHeader><DialogTitle>Novo paciente</DialogTitle><DialogDescription>Cadastre os dados administrativos essenciais.</DialogDescription></DialogHeader><form className="grid gap-4 sm:grid-cols-2" onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); void run({ action: "create_patient", nome: form.get("nome"), nascimento: form.get("nascimento"), cpf: form.get("cpf"), telefone: form.get("telefone"), endereco: form.get("endereco"), contatoEmergencia: form.get("contatoEmergencia"), observacoesAdmin: form.get("observacoesAdmin") }, "Paciente cadastrado.", () => setOpen(false)); }}><Field label="Nome completo"><Input name="nome" required autoFocus /></Field><Field label="Data de nascimento"><Input name="nascimento" type="date" required /></Field><Field label="CPF (opcional)"><Input name="cpf" inputMode="numeric" /></Field><Field label="Telefone"><Input name="telefone" required placeholder="(85) 99999-9999" /></Field><Field label="Endereço"><Input name="endereco" /></Field><Field label="Contato de emergência"><Input name="contatoEmergencia" /></Field><div className="sm:col-span-2"><Field label="Observações administrativas"><Textarea name="observacoesAdmin" rows={3} /></Field></div><DialogFooter className="sm:col-span-2"><Button type="button" variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button disabled={saving}>{saving && <Loader2 className="animate-spin" />}Salvar paciente</Button></DialogFooter></form></DialogContent></Dialog>; }
function StockDialog({ open, setOpen, products, run, saving }: { open: boolean; setOpen: (value: boolean) => void; products: Product[]; run: (action: Record<string, unknown>, success: string, close?: () => void) => Promise<void>; saving: boolean }) { const [productId, setProductId] = useState(""); return <Dialog open={open} onOpenChange={setOpen}><DialogContent><DialogHeader><DialogTitle>Entrada de estoque</DialogTitle><DialogDescription>Informe lote e validade para manter a rastreabilidade.</DialogDescription></DialogHeader><form className="space-y-4" onSubmit={(event) => { event.preventDefault(); const form = new FormData(event.currentTarget); void run({ action: "receive_stock", produtoId: Number(productId), numero: form.get("numero"), validade: form.get("validade"), quantidade: Number(form.get("quantidade")) }, "Entrada registrada.", () => setOpen(false)); }}><Field label="Produto"><Select value={productId} onValueChange={setProductId}><SelectTrigger className="w-full"><SelectValue placeholder="Selecione" /></SelectTrigger><SelectContent>{products.map((product) => <SelectItem key={product.id} value={String(product.id)}>{product.nome} · {product.apresentacao}</SelectItem>)}</SelectContent></Select></Field><div className="grid gap-4 sm:grid-cols-2"><Field label="Número do lote"><Input name="numero" required /></Field><Field label="Validade"><Input name="validade" type="date" required /></Field></div><Field label="Quantidade recebida"><Input name="quantidade" type="number" min="0.01" step="0.01" required /></Field><DialogFooter><Button type="button" variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button disabled={saving || !productId}>Registrar entrada</Button></DialogFooter></form></DialogContent></Dialog>; }
function newDraft(key: string, productId = ""): DraftItem { return { key, produtoId: productId, dose: "", via: "IM", quantidade: "1", instrucoes: "", recorrenciaDias: "" }; }
function PrescriptionDialog({ open, setOpen, patients, products, run, saving }: { open: boolean; setOpen: (value: boolean) => void; patients: Patient[]; products: Product[]; run: (action: Record<string, unknown>, success: string, close?: () => void) => Promise<void>; saving: boolean }) {
  const [patientId, setPatientId] = useState(""), [items, setItems] = useState<DraftItem[]>([]); useEffect(() => { if (!open) { setPatientId(""); setItems([]); } }, [open]);
  const update = (key: string, field: keyof Omit<DraftItem, "key">, value: string) => setItems((current) => current.map((item) => item.key === key ? { ...item, [field]: value } : item)); const addItem = (productId = "") => setItems((current) => [...current, newDraft(crypto.randomUUID(), productId)]);
  const addCombo = () => { const combo = products.filter((product) => /vitamina\s*(b12|d3)/i.test(product.nome)); const existing = new Set(items.map((item) => item.produtoId)); const additions = combo.filter((product) => !existing.has(String(product.id))); if (!additions.length) return toast.message("B12 e D3 já estão nos itens prescritos."); setItems((current) => [...current, ...additions.map((product) => newDraft(crypto.randomUUID(), String(product.id)))]); };
  return <Dialog open={open} onOpenChange={setOpen}><DialogContent className="max-h-[92vh] max-w-4xl overflow-y-auto"><DialogHeader><DialogTitle>Nova prescrição</DialogTitle><DialogDescription>Os itens são independentes: cada injetável pode ter sua própria dose, via e recorrência.</DialogDescription></DialogHeader><form className="space-y-6" onSubmit={(event) => { event.preventDefault(); void run({ action: "create_prescription", pacienteId: Number(patientId), itens: items.map((item) => ({ produtoId: Number(item.produtoId), dose: item.dose, via: item.via, quantidade: Number(item.quantidade), instrucoes: item.instrucoes, recorrenciaDias: Number(item.recorrenciaDias) })), observacoes: new FormData(event.currentTarget).get("observacoes") }, "Prescrição finalizada.", () => setOpen(false)); }}><Field label="Paciente"><Select value={patientId} onValueChange={setPatientId}><SelectTrigger className="w-full"><SelectValue placeholder="Selecione o paciente" /></SelectTrigger><SelectContent>{patients.map((patient) => <SelectItem key={patient.id} value={String(patient.id)}>{patient.nome}</SelectItem>)}</SelectContent></Select></Field><div className="rounded-2xl border border-cyan-100 bg-[#f6fbfd] p-4 sm:p-5"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><h3 className="font-semibold">Itens prescritos</h3><p className="mt-1 text-sm text-slate-500">Inclua uma ou mais injetáveis no mesmo documento.</p></div><div className="flex flex-wrap gap-2"><Button type="button" variant="outline" size="sm" onClick={addCombo}>B12 + D3</Button><Button type="button" size="sm" onClick={() => addItem()}><Plus />Adicionar injetável</Button></div></div><div className="mt-4 space-y-4">{items.map((item, index) => <div key={item.key} className="relative rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><div className="mb-4 flex items-center justify-between"><span className="text-sm font-bold text-cyan-800">Item {index + 1}</span><Button type="button" variant="ghost" size="icon" aria-label="Remover item" onClick={() => setItems((current) => current.filter((entry) => entry.key !== item.key))}><Trash2 className="h-4 w-4 text-slate-500" /></Button></div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3"><Field label="Injetável"><Select value={item.produtoId} onValueChange={(value) => update(item.key, "produtoId", value)}><SelectTrigger className="w-full"><SelectValue placeholder="Selecione" /></SelectTrigger><SelectContent>{products.map((product) => <SelectItem key={product.id} value={String(product.id)} disabled={items.some((entry) => entry.key !== item.key && entry.produtoId === String(product.id))}>{product.nome} · {product.apresentacao}</SelectItem>)}</SelectContent></Select></Field><Field label="Dose"><Input value={item.dose} required onChange={(event) => update(item.key, "dose", event.target.value)} placeholder="Ex.: 1 mL" /></Field><Field label="Via"><Select value={item.via} onValueChange={(value) => update(item.key, "via", value)}><SelectTrigger className="w-full"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="IM">Intramuscular (IM)</SelectItem><SelectItem value="IV">Intravenosa (IV)</SelectItem><SelectItem value="SC">Subcutânea (SC)</SelectItem></SelectContent></Select></Field><Field label="Quantidade"><Input value={item.quantidade} type="number" min="0.01" step="0.01" required onChange={(event) => update(item.key, "quantidade", event.target.value)} /></Field><Field label="Recorrência em dias"><Input value={item.recorrenciaDias} type="number" min="1" placeholder="Opcional" onChange={(event) => update(item.key, "recorrenciaDias", event.target.value)} /></Field><div className="sm:col-span-2 lg:col-span-3"><Field label="Instruções"><Textarea value={item.instrucoes} rows={2} onChange={(event) => update(item.key, "instrucoes", event.target.value)} placeholder="Orientações para este item" /></Field></div></div></div>)}{!items.length && <div className="rounded-xl border border-dashed border-cyan-200 bg-white px-5 py-8 text-center text-sm text-slate-500">Use “B12 + D3” ou adicione um injetável para iniciar.</div>}</div></div><Field label="Observações gerais"><Textarea name="observacoes" rows={2} placeholder="Observações da prescrição" /></Field><DialogFooter><Button type="button" variant="outline" onClick={() => setOpen(false)}>Cancelar</Button><Button disabled={saving || !patientId || !items.length || items.some((item) => !item.produtoId || !item.dose || !Number(item.quantidade))}>Finalizar prescrição</Button></DialogFooter></form></DialogContent></Dialog>;
}
function ApplicationDialog({ rx, setRx, lots, applications, run, saving }: { rx: Prescription | null; setRx: (rx: Prescription | null) => void; lots: Lot[]; applications: Application[]; run: (action: Record<string, unknown>, success: string, close?: () => void) => Promise<void>; saving: boolean }) {
  const items = useMemo(() => rx ? pendingItems(rx, applications) : [], [rx, applications]); const [selected, setSelected] = useState<number[]>([]), [lotValues, setLotValues] = useState<Record<number, string>>({});
  useEffect(() => { const nextSelected = items.map((item) => item.id); const nextLots: Record<number, string> = {}; items.forEach((item) => { const lot = lots.filter((entry) => entry.produtoId === item.produtoId && entry.saldo >= item.quantidade && entry.validade >= today()).sort((a, b) => a.validade.localeCompare(b.validade))[0]; if (lot) nextLots[item.id] = String(lot.id); }); setSelected(nextSelected); setLotValues(nextLots); }, [rx, items, lots]);
  const toggle = (id: number) => setSelected((current) => current.includes(id) ? current.filter((entry) => entry !== id) : [...current, id]);
  return <Dialog open={!!rx} onOpenChange={(value) => !value && setRx(null)}><DialogContent className="max-h-[92vh] overflow-y-auto sm:max-w-2xl"><DialogHeader><DialogTitle>Confirmar aplicação</DialogTitle><DialogDescription>{rx ? `${rx.pacienteNome} · selecione os itens que serão aplicados agora.` : ""}</DialogDescription></DialogHeader><form className="space-y-5" onSubmit={(event) => { event.preventDefault(); if (!rx) return; const form = new FormData(event.currentTarget); void run({ action: "apply_prescription", prescricaoId: rx.id, itens: items.filter((item) => selected.includes(item.id)).map((item) => ({ itemPrescricaoId: item.id, loteId: Number(lotValues[item.id]) })), localAplicacao: form.get("localAplicacao"), observacoes: form.get("observacoes"), reacao: form.get("reacao") }, "Aplicação confirmada e estoque atualizado.", () => setRx(null)); }}><div className="space-y-3">{items.map((item) => { const validLots = lots.filter((lot) => lot.produtoId === item.produtoId && lot.saldo >= item.quantidade && lot.validade >= today()).sort((a, b) => a.validade.localeCompare(b.validade)); const active = selected.includes(item.id); return <div key={item.id} className={`rounded-xl border p-4 transition ${active ? "border-cyan-300 bg-cyan-50/45" : "border-slate-200 bg-white"}`}><div className="flex gap-3"><input id={`apply-${item.id}`} type="checkbox" className="mt-1 h-4 w-4 accent-cyan-700" checked={active} onChange={() => toggle(item.id)} /><div className="min-w-0 flex-1"><label htmlFor={`apply-${item.id}`} className="cursor-pointer font-semibold">{item.produtoNome}</label><p className="mt-1 text-sm text-slate-500">{item.dose} · {item.via} · {item.quantidade} unidade(s)</p>{active && <div className="mt-3"><Field label="Lote — sugestão FEFO"><Select value={lotValues[item.id] ?? ""} onValueChange={(value) => setLotValues((current) => ({ ...current, [item.id]: value }))}><SelectTrigger className="w-full bg-white"><SelectValue placeholder="Selecione o lote" /></SelectTrigger><SelectContent>{validLots.map((lot, index) => <SelectItem key={lot.id} value={String(lot.id)}>{index === 0 ? "Recomendado · " : ""}Lote {lot.numero} · vence {fmtDate(lot.validade)} · saldo {lot.saldo}</SelectItem>)}</SelectContent></Select></Field>{!validLots.length && <p className="mt-2 text-sm font-medium text-rose-600">Não há lote válido com saldo suficiente.</p>}</div>}</div></div></div>; })}</div><div className="grid gap-4 sm:grid-cols-2"><Field label="Local da aplicação"><Input name="localAplicacao" required placeholder="Ex.: deltoide direito" /></Field><Field label="Reação observada"><Input name="reacao" placeholder="Nenhuma ou descreva" /></Field></div><Field label="Observações"><Textarea name="observacoes" rows={2} /></Field><DialogFooter><Button type="button" variant="outline" onClick={() => setRx(null)}>Cancelar</Button><Button disabled={saving || !selected.length || selected.some((id) => !lotValues[id])}><Syringe />Confirmar e baixar estoque</Button></DialogFooter></form></DialogContent></Dialog>;
}
function PrescriptionPrint({ rx, onClose }: { rx: Prescription; onClose: () => void }) { return <div className="print-sheet hidden bg-white p-12 text-[#10203b] print:block"><div className="flex items-center gap-5 border-b-2 border-cyan-700 pb-6"><img src="/logo.jpg" alt="CTI" className="h-20 w-20 object-contain" /><div><h1 className="text-2xl font-bold text-[#071c42]">CTI — Centro de Terapias Integradas</h1><p className="mt-1 text-sm">Prescrição médica para aplicação presencial</p></div></div><div className="mt-8 grid grid-cols-2 gap-5 text-sm"><PrintInfo label="Paciente" value={rx.pacienteNome} /><PrintInfo label="Data de emissão" value={fmtDate(rx.finalizadoEm || rx.criadoEm)} /><PrintInfo label="Médico" value={rx.medicoNome} /><PrintInfo label="Número" value={`#${String(rx.id).padStart(5, "0")}`} /></div><table className="mt-9 w-full border-collapse text-sm"><thead><tr className="border-y-2 border-[#071c42] text-left"><th className="py-3">Injetável</th><th>Dose</th><th>Via</th><th>Quantidade</th><th>Instruções</th></tr></thead><tbody>{rx.items.map((item) => <tr key={item.id} className="border-b border-slate-200 align-top"><td className="py-4 pr-3"><strong>{item.produtoNome}</strong><br /><span className="text-slate-500">{item.apresentacao}</span></td><td>{item.dose}</td><td>{item.via}</td><td>{item.quantidade}</td><td>{item.instrucoes || "—"}</td></tr>)}</tbody></table>{rx.observacoes && <div className="mt-6"><PrintInfo label="Observações" value={rx.observacoes} /></div>}<div className="mt-28 text-center"><div className="mx-auto w-80 border-t border-slate-500 pt-2 text-sm">{rx.medicoNome}<br />CRM configurado no cadastro profissional</div></div><p className="mt-20 border-t border-slate-200 pt-4 text-xs text-slate-500">Documento destinado à impressão e assinatura manual. Não possui assinatura digital.</p><button className="print:hidden" onClick={onClose}>Fechar</button></div>; }
function PrintInfo({ label, value }: { label: string; value: string }) { return <div><span className="block text-xs font-bold uppercase tracking-wide text-slate-400">{label}</span><strong className="mt-1 block font-medium">{value}</strong></div>; }
